function freqLabel(b){
  const f=b.frequency||(b.monthly?'monthly':'once');
  if(f==='everyXDays')return `every ${b.intervalDays||30} days`;
  return f;
}
function daysUntilDue(dateStr){
  const a=new Date(today()+'T00:00:00'),b=new Date(dateStr+'T00:00:00');
  return Math.round((b-a)/86400000);
}

bills=()=>{
  let rows=state.bills.filter(b=>!b.paid&&!b.cancelled).sort((a,b)=>a.date.localeCompare(b.date));
  const schedActive=state.settings.alwaysOnScheduler!==false;
  return `<section class="card"><div class="section-head"><h2>BNPL, PTPTN & Bill Scheduler</h2>${actionButton('＋ Custom Reminder','addBill')}</div><div class="hint" style="margin-top:0">${icon('bell')}${schedActive?'Always-On Task Scheduler is active — reminders fire at your configured timeslot before due date and auto-restart on phone reboot.':'Task scheduler is paused. Enable Always-On Task Scheduler in Settings.'}</div><p class="note" style="margin:10px 0 8px"><strong>1-Tap Quick Templates (Pay Before Due Date):</strong></p><div class="tools-grid" style="margin-bottom:14px">${actionButton('＋ PTPTN Loan','presetReminder','ptptn')}${actionButton('＋ SPayLater','presetReminder','spaylater')}${actionButton('＋ GrabPayLater','presetReminder','grabpaylater')}${actionButton('＋ Atome BNPL','presetReminder','atome')}${actionButton('＋ Credit Card','presetReminder','creditcard')}${actionButton('Test Alert Now','testReminder','')}</div>${rows.map(b=>{
    const rType=b.reminderType||'bill';
    const badge=rType==='bnpl'?'BNPL':rType==='ptptn'?'PTPTN':rType==='credit'?'Credit Card':'Bill';
    const diff=daysUntilDue(b.date);
    const overdue=diff<0;
    const urgClass=overdue?'overdue':diff<=3?'soon':'ok';
    const urgText=overdue?`OVERDUE · ${Math.abs(diff)}d ago`:diff===0?`Due Today · ${b.remindTime||'09:00'}`:`Due in ${diff}d · ${b.remindTime||'09:00'}`;
    return `<div class="bnpl-card type-${esc(rType)}"><div class="flex between"><span class="tag">${esc(badge)} · ${esc(freqLabel(b))}</span><span class="urgency-pill ${urgClass}">${esc(urgText)}</span></div><div class="flex between" style="margin-top:10px"><div><h3>${esc(b.name)}</h3><p>Due ${esc(b.date)} · Remind ${b.remindDaysBefore??3}d before at ${esc(b.remindTime||'09:00')}</p><div class="tx-meta-row"><span class="tx-pill">${esc(b.category)}${b.subcategory?' › '+esc(b.subcategory):''}</span>${b.variable?`<span class="tx-pill">Variable</span>`:''}</div>${b.cancelDate?`<p>Cancel by ${esc(b.cancelDate)}</p>`:''}</div><strong class="money" style="font-size:18px">${money(b.amount)}</strong></div><div class="tools-grid" style="margin-top:12px">${actionButton('Record payment','payBill',b.id)}${actionButton('Test alert','testReminder',b.id,'ghost')}${actionButton('Edit','editBill',b.id,'ghost')}${actionButton('Remove','deleteBillExtra',b.id,'danger')}</div></div>`;
  }).join('')||empty('plan','Never miss a BNPL or PTPTN due date','Tap a template above (PTPTN, SPayLater, GrabPayLater, Atome) or add a custom schedule to get notified before your due date.','Add reminder','addBill')}</section>${reportData?.subscriptions.length?`<section class="card"><h2>Possible subscriptions</h2><p class="note">Three similar, regularly spaced payments. Confirm before creating a plan.</p>${reportData.subscriptions.map((s,i)=>`<div class="setting-row"><div class="grow"><h3>${esc(s.name)}</h3><p>${money(s.amount)} · ${esc(s.frequency)}</p></div>${actionButton('Review','subscription',String(i))}</div>`).join('')}</section>`:''}${state.bills.some(b=>b.cancelled)?`<details class="card"><summary>Paused plans</summary>${state.bills.filter(b=>b.cancelled).map(b=>`<div class="setting-row"><span class="grow">${esc(b.name)}</span>${actionButton('Edit','editBill',b.id)}</div>`).join('')}</details>`:''}`;
};

function computeLocalTax(prof){
  const base=Number(prof.monthlyBaseSalary||0),bonus=Number(prof.annualBonus||0),other=Number(prof.otherIncome||0),epfRate=Number(prof.epfRate??11),pcb=Number(prof.monthlyPcb||0);
  const grossSen=Math.round((base*12+bonus+other)*100);
  const autoEpf=Math.min(400000,Math.round(grossSen*(epfRate/100)));
  const ind=900000;
  const epf=Math.min(400000,prof.epfRelief!==undefined&&prof.epfRelief!==''?Math.round(Number(prof.epfRelief)*100):autoEpf);
  const life=Math.min(300000,Math.round(Number(prof.lifeInsurance||0)*100));
  const medIns=Math.min(300000,Math.round(Number(prof.medicalInsurance||0)*100));
  const socso=Math.min(35000,Math.round(Number(prof.socso??(base>0?350:0))*100));
  const lifeSt=Math.min(250000,Math.round(Number(prof.lifestyle||0)*100));
  const sports=Math.min(100000,Math.round(Number(prof.sports||0)*100));
  const med=Math.min(1000000,Math.round(Number(prof.medical||0)*100));
  const edu=Math.min(700000,Math.round(Number(prof.education||0)*100));
  const sspn=Math.min(800000,Math.round(Number(prof.sspnPrs||0)*100));
  const fam=Math.min(2000000,Math.round(Number(prof.familyRelief||0)*100));
  const reliefs=ind+epf+life+medIns+socso+lifeSt+sports+med+edu+sspn+fam;
  const chargeable=Math.max(0,grossSen-reliefs);
  const tiers=[[0,500000,0],[500000,2000000,1],[2000000,3500000,3],[3500000,5000000,6],[5000000,7000000,11],[7000000,10000000,19],[10000000,40000000,25],[40000000,60000000,26],[60000000,200000000,28],[200000000,Infinity,30]];
  let grossTax=0;const brackets=[];
  for(const [from,to,rate] of tiers){
    if(chargeable<=from)break;
    const tx=Math.min(chargeable,to)-from;
    const tAmt=Math.round(tx*(rate/100));
    grossTax+=tAmt;
    brackets.push({from,to:to===Infinity?-1:to,rate,taxable:tx,tax:tAmt});
  }
  const statReb=(chargeable>0&&chargeable<=3500000)?40000:0;
  const zakat=Math.round(Number(prof.zakat||0)*100);
  const netTax=Math.max(0,grossTax-statReb-zakat);
  const annualPcb=Math.round(pcb*12*100);
  return {year:new Date().getFullYear(),annualGross:grossSen,totalReliefs:reliefs,chargeableIncome:chargeable,grossTax,statutoryRebate:statReb,zakatRebate:zakat,netTaxPayable:netTax,monthlyTaxEquivalent:Math.round(netTax/12),annualPcbPaid:annualPcb,pcbDifference:netTax-annualPcb,effectiveRate:grossSen>0?(netTax*100/grossSen).toFixed(2):'0.00',brackets,ledgerDetected:reportData?.taxEstimate?.ledgerDetected||{}};
}

function reliefMeter(val,cap){
  const num=Math.max(0,Number(val)||0);
  const pct=Math.min(100,Math.round(num/cap*100));
  return `<div class="relief-meter"><span style="width:${pct}%"></span></div>`;
}

window.taxView=()=>{
  const p=state.settings.taxProfile||{};
  const est=reportData?.taxEstimate||computeLocalTax(p);
  const det=est.ledgerDetected||{};
  const refund=est.pcbDifference<0;
  const gross=Math.max(1,est.annualGross);
  const shielded=Math.min(est.annualGross,est.totalReliefs);
  const netTax=Math.min(est.annualGross,est.netTaxPayable);
  const takeHome=Math.max(0,est.annualGross-netTax);
  const pShield=Math.round(shielded/gross*100),pTax=Math.max(est.netTaxPayable>0?2:0,Math.round(netTax/gross*100)),pHome=Math.max(0,100-pShield-pTax);
  const vLife=p.lifestyle??(det.lifestyle?(det.lifestyle/100).toFixed(2):'');
  const vSports=p.sports??(det.sports?(det.sports/100).toFixed(2):'');
  const vMed=p.medical??(det.medical?(det.medical/100).toFixed(2):'');
  const vLifeIns=p.lifeInsurance??(det.lifeInsurance?(det.lifeInsurance/100).toFixed(2):'');
  const vMedIns=p.medicalInsurance??(det.medicalInsurance?(det.medicalInsurance/100).toFixed(2):'');
  const vEdu=p.education??(det.education?(det.education/100).toFixed(2):'');
  const vSspn=p.sspnPrs??(det.sspnPrs?(det.sspnPrs/100).toFixed(2):'');
  return `<div class="stack"><section class="card hero"><div class="flex between"><span class="eyebrow">MALAYSIA LHDN TAX ESTIMATOR (YA ${est.year||new Date().getFullYear()})</span>${icon('shield')}</div><div class="balance money"><span>RM</span>${(est.netTaxPayable/100).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2})}</div><small>Estimated Annual Net Tax Payable · Effective rate ${esc(est.effectiveRate)}% · Monthly eq. ${money(est.monthlyTaxEquivalent)}</small><div class="hero-foot"><div class="hero-stat-box"><div class="label">Chargeable Income</div><strong class="money">${money(est.chargeableIncome)}</strong></div><div class="hero-stat-box"><div class="label">${refund?'Estimated PCB Refund':'PCB Top-Up Needed'}</div><strong class="money">${refund?'+':''}${money(Math.abs(est.pcbDifference))}</strong></div></div></section><section class="card"><h2>Income Allocation & Relief Shield</h2><p class="note">Visualizing how your LHDN tax reliefs shield your gross annual income (${money(est.annualGross)}).</p><div class="tax-stack-bar" role="img" aria-label="Income allocation bar"><div class="seg-home" style="width:${pHome}%" title="Taxable Take-Home (${pHome}%)"></div><div class="seg-relief" style="width:${pShield}%" title="Shielded by Reliefs (${pShield}%)"></div><div class="seg-tax" style="width:${pTax}%" title="Net Tax (${pTax}%)"></div></div><div class="flex between" style="font-size:11px;flex-wrap:wrap"><span class="flex"><i class="dot" style="background:var(--accent);width:9px;height:9px;border-radius:3px;display:inline-block"></i>Take-home ${money(takeHome)}</span><span class="flex"><i class="dot" style="background:var(--accent-soft);width:9px;height:9px;border-radius:3px;display:inline-block"></i>Relief shield ${money(est.totalReliefs)}</span><span class="flex"><i class="dot" style="background:var(--danger);width:9px;height:9px;border-radius:3px;display:inline-block"></i>Net tax ${money(est.netTaxPayable)}</span></div></section><section class="card"><div class="section-head"><h2>Income, Reliefs & Rebates</h2><button type="button" class="btn secondary small" data-action="autoFillTaxReliefs">Auto-fill from recorded expenses</button></div><p class="note">Enter your base salary, bonus, and LHDN reliefs below. Everything is calculated and saved privately on your device.</p><form data-extra="taxProfile" id="tax-profile-form"><h3>1. Employment & Other Income</h3><div class="form-grid">${field('Monthly Base Salary (RM)','monthlyBaseSalary',p.monthlyBaseSalary??'','number','step="0.01" min="0" placeholder="e.g. 5500"')}${field('Annual Bonus / Commission (RM)','annualBonus',p.annualBonus??'','number','step="0.01" min="0" placeholder="e.g. 5500"')}</div><div class="form-grid">${field('Other Annual Taxable Income (RM)','otherIncome',p.otherIncome??'','number','step="0.01" min="0" placeholder="0.00"')}${field('Employee EPF (KWSP) Rate (%)','epfRate',p.epfRate??11,'number','step="0.5" min="0" max="20"')}</div>${field('Monthly PCB / MTD Deducted (RM)','monthlyPcb',p.monthlyPcb??'','number','step="0.01" min="0" placeholder="e.g. 120.00"')}<h3>2. LHDN Tax Reliefs (Annual RM)</h3><p class="note">Individual & dependent statutory relief of <strong>RM 9,000</strong> is applied automatically. Progress bars show cap utilization.</p><div class="form-grid"><div>${field('EPF / KWSP (Cap RM 4,000)','epfRelief',p.epfRelief??'','number','step="0.01" min="0" max="4000" placeholder="Auto from EPF %"')}${reliefMeter(p.epfRelief||4000,4000)}</div><div>${field('SOCSO / PERKESO & EIS (Cap RM 350)','socso',p.socso??350,'number','step="0.01" min="0" max="350"')}${reliefMeter(p.socso??350,350)}</div></div><div class="form-grid"><div>${field(`Lifestyle: Books, PC, Phone, WiFi (Cap RM 2,500 · Ledger: ${money(det.lifestyle||0)})`,'lifestyle',vLife,'number','step="0.01" min="0" max="2500"')}${reliefMeter(vLife,2500)}</div><div>${field(`Sports Equipment & Gym (Cap RM 1,000 · Ledger: ${money(det.sports||0)})`,'sports',vSports,'number','step="0.01" min="0" max="1000"')}${reliefMeter(vSports,1000)}</div></div><div class="form-grid"><div>${field(`Medical, Checkup & Parents (Cap RM 10,000 · Ledger: ${money(det.medical||0)})`,'medical',vMed,'number','step="0.01" min="0" max="10000"')}${reliefMeter(vMed,10000)}</div><div>${field(`Life Insurance / Family Takaful (Cap RM 3,000 · Ledger: ${money(det.lifeInsurance||0)})`,'lifeInsurance',vLifeIns,'number','step="0.01" min="0" max="3000"')}${reliefMeter(vLifeIns,3000)}</div></div><div class="form-grid"><div>${field(`Medical & Education Insurance (Cap RM 3,000 · Ledger: ${money(det.medicalInsurance||0)})`,'medicalInsurance',vMedIns,'number','step="0.01" min="0" max="3000"')}${reliefMeter(vMedIns,3000)}</div><div>${field(`Self Education / Upskilling (Cap RM 7,000 · Ledger: ${money(det.education||0)})`,'education',vEdu,'number','step="0.01" min="0" max="7000"')}${reliefMeter(vEdu,7000)}</div></div><div class="form-grid"><div>${field(`SSPN / PRS / EV Charging (Cap RM 8,000 · Ledger: ${money(det.sspnPrs||0)})`,'sspnPrs',vSspn,'number','step="0.01" min="0" max="8000"')}${reliefMeter(vSspn,8000)}</div><div>${field('Spouse / Child / OKU Reliefs (RM)','familyRelief',p.familyRelief??'','number','step="0.01" min="0" placeholder="0.00"')}${reliefMeter(p.familyRelief||0,20000)}</div></div><h3>3. Tax Rebates (Direct Offset)</h3>${field(`Zakat / Fitrah Paid (RM · 100% rebate · Ledger: ${money(det.zakat||0)})`,'zakat',p.zakat??(det.zakat?(det.zakat/100).toFixed(2):''),'number','step="0.01" min="0" placeholder="0.00"')}<p class="note">Statutory RM 400 individual rebate is applied automatically if Chargeable Income ≤ RM 35,000.</p>${formFooter('Calculate & Save Tax Estimate')}</form></section><section class="card"><h2>LHDN Calculation Breakdown</h2>${[['Annual Gross Income',money(est.annualGross)],['Less: Total Tax Reliefs (incl. RM 9,000 Individual)','−'+money(est.totalReliefs)],['Chargeable Income',money(est.chargeableIncome)],['Gross Tax Before Rebates',money(est.grossTax)],...(est.statutoryRebate?[['Less: Statutory Rebate (Chargeable ≤ RM 35k)','−'+money(est.statutoryRebate)]]:[]),...(est.zakatRebate?[['Less: Zakat / Fitrah Rebate','−'+money(est.zakatRebate)]]:[]),['Net Tax Payable',money(est.netTaxPayable)],['Monthly Tax Equivalent',money(est.monthlyTaxEquivalent)],['Annual PCB Deducted',money(est.annualPcbPaid)],[refund?'Estimated LHDN Tax Refund':'Estimated Balance Tax to Pay',(refund?'Refund ':'Pay ')+money(Math.abs(est.pcbDifference))]].map(([l,v])=>`<div class="detail-line"><span>${esc(l)}</span><strong>${esc(v)}</strong></div>`).join('')}${est.brackets?.length?`<h3 style="margin-top:16px">Progressive Tax Tiers Applied</h3>${est.brackets.map(b=>`<div class="detail-line"><span>${money(b.from)} – ${b.to<0?'Above':money(b.to)} (${b.rate}%)</span><span>Taxable ${money(b.taxable)} → <strong>${money(b.tax)}</strong></span></div>`).join('')}`:''}</section></div>`;
};

function categoriesModal(){
  const active=activeCategories();
  modal('Categories & Subcategories',`<p class="note">Add new categories or subcategories, or tap ✕ on any category or subcategory chip to remove it.</p><div class="stack" style="gap:12px"><form data-extra="addSubcategory" class="soft-card" style="margin:0"><h3>Add a subcategory</h3><div class="form-grid">${select('Under category','category',active.map(c=>[c[0],c[0]]),active[0]?.[0]||'Food & drinks')}${field('New subcategory name','subcategory','','text','required maxlength="80" placeholder="e.g. Bubble Tea, Tol PLUS"')}</div>${formFooter('Add subcategory')}</form><form data-extra="category" class="soft-card" style="margin:0"><h3>Add a main category</h3><div class="form-grid">${field('New category name','name','','text','required maxlength="60" placeholder="e.g. Pets & Vet"')}${select('Icon','icon',[['wallet','Wallet'],['heart','Heart'],['food','Food'],['car','Car'],['target','Goal'],['bag','Shopping'],['bolt','Utilities'],['shield','Shield']],'wallet')}</div>${select('Color','color',[['sage','Sage'],['peach','Peach'],['purple','Lavender'],['blue','Blue']],'sage')}${formFooter('Add category')}</form><div class="review-list" style="max-height:340px">${active.map(c=>{
    const subs=subcategoriesFor(c[0]);
    return `<div class="plan-row" style="padding:10px 0"><div class="flex between"><strong>${esc(c[0])}</strong><button type="button" class="row-menu" data-action="removeCategory" data-name="${esc(c[0])}" title="Remove category ${esc(c[0])}">✕</button></div><div class="category-chips" style="margin-top:6px;display:flex;flex-wrap:wrap;gap:6px">${subs.map(s=>`<span class="tag" style="display:inline-flex;align-items:center;gap:4px">${esc(s)}<button type="button" data-action="removeSubcategory" data-category="${esc(c[0])}" data-subcategory="${esc(s)}" style="border:0;background:transparent;padding:0 2px;cursor:pointer;font-size:11px;line-height:1" title="Remove subcategory">✕</button></span>`).join('')||'<span class="muted" style="font-size:11px">No subcategories</span>'}</div></div>`;
  }).join('')}</div></div>`);
}

const baseInbox=inbox;
inbox=()=>baseInbox().replace('<div class="stack">',`<div class="stack"><div class="tools-grid">${actionButton('Scan receipt','scan')}${actionButton('Paste text','paste')}${actionButton('Send test notification','testNotification')}${actionButton('Review together','batch')}</div>`).replace(/<button class="btn ghost" data-action="ignore" data-id="([^"]+)">Ignore<\/button>/g,`<button class="btn ghost" data-action="ignore" data-id="$1">Ignore</button>${actionButton('Already recorded?','linkDraft','$1','ghost')}`);
const baseTxForm=txForm;
txForm=(data={})=>{data={account:data.draftId?'':state.settings.lastAccount,category:state.settings.lastCategory||'Miscellaneous',...data};baseTxForm(data);let form=$('#transaction-form');if(data.kind==='shared')form.querySelector('.chips').insertAdjacentHTML('beforeend','<span class="chip active">Shared expense</span>');if(data.kind==='reimbursement')form.querySelector('.chips').innerHTML='<span class="chip active">Repayment received</span>';let evidence=data.amountCandidates?.length>1?`<p class="note">Amounts found: ${data.amountCandidates.map(money).join(' · ')}. Choose the actual payment amount above.</p>`:'';let html=data.receiptId?`<img class="receipt-thumb" src="/receipt/${esc(data.receiptId)}" alt="Attached receipt">`:'';if(!data.kind||['expense','refund','shared'].includes(data.kind))html+=subcategorySelect(data.category||'Miscellaneous',data.subcategory||'');if(data.kind==='shared')html+=`${field('Your own share (RM)','ownAmount',data.ownAmount||'0','text','required inputmode="decimal"')}${field('Who owes the rest?','person',data.person||'','text','required maxlength="80"')}`;html+=`${field('Tags · comma separated','tags',Array.isArray(data.tags)?data.tags.join(', '):data.tags||'','text','maxlength="200" placeholder="work, holiday"')}`;
if(!data.kind||['expense','refund'].includes(data.kind))html+=`<details ${data.splits?.length?'open':''}><summary>Split across categories</summary><div id="split-rows">${(Array.isArray(data.splits)?data.splits:[]).map(splitRow).join('')}</div>${actionButton('Add category split','addSplit')}<p class="note">Splits must add up to the full payment above.</p></details>`;
const prevCount=data.editId&&data.merchant?sameMerchantCount(data.merchant,data.editId):0;
html+=`<details ${data.originalCurrency?'open':''}><summary>Foreign currency details</summary><div class="form-grid">${field('Original currency','originalCurrency',data.originalCurrency||'','text','maxlength="3" placeholder="USD"')}${field('Original amount','originalAmount',data.originalAmount||'','text','inputmode="decimal"')}</div>${field('Included conversion fees (MYR)','foreignFee',data.foreignFee||'0','text','inputmode="decimal"')}<p class="note">Enter the actual settled MYR amount at the top, including any fees. The implied rate is saved with this record.</p></details>${prevCount>0?check(`Update ${prevCount} previous "${esc(data.merchant)}" transaction${prevCount===1?'':'s'} to this category & remember for future`,'applyHistory',data.category==='Miscellaneous'||data.category==='Other'):''}${check('Remember merchant category and account for next time','rememberRule',data.editId&&(data.category==='Miscellaneous'||data.category==='Other'))}`;form.querySelector('.error').insertAdjacentHTML('beforebegin',evidence+html);};
function splitRow(s={}){return `<div class="split-row">${select('Split category','splitCategory',activeCategories().map(c=>[c[0],c[0]]),s.category||'Miscellaneous')}${field('RM','splitAmount',s.amount||'','text','inputmode="decimal" required')}<button type="button" class="row-menu" data-action="removeSplit" aria-label="Remove split">${icon('close')}</button></div>`}
window.enrichTransaction=(args,form)=>{args.rememberRule=!!form.elements.rememberRule?.checked;args.applyHistory=!!form.elements.applyHistory?.checked;args.tags=(args.tags||'').split(',').map(x=>x.trim()).filter(Boolean);const rows=[...form.querySelectorAll('.split-row')];if(rows.length)args.splits=rows.map(row=>({category:row.querySelector('select').value,amount:row.querySelector('input').value}));delete args.splitCategory;delete args.splitAmount;if(!args.originalCurrency&&!args.originalAmount){delete args.originalCurrency;delete args.originalAmount;delete args.foreignFee}else{if(!args.originalCurrency||!Number.isFinite(Number(args.originalAmount))||Number(args.originalAmount)<=0)throw new Error('Enter both the original currency and a positive amount.');if(!/^\d+([.]\d{1,2})?$/.test(args.foreignFee)||Number(args.foreignFee)>Number(args.amount))throw new Error('Included fees must be between zero and the MYR total.');args.exchangeRate=((Number(args.amount)-Number(args.foreignFee))/Number(args.originalAmount)).toFixed(8)}};
const baseDetail=detail;
detail=id=>{baseDetail(id);let t=state.transactions.find(x=>x.id===id);if(['opening','adjustment'].includes(t.kind))$('.modal .form-footer').innerHTML=actionButton('Remove adjustment','quickRemove',id,'danger');$('.modal').insertAdjacentHTML('beforeend',`<div class="tools-grid section-space">${actionButton('Repeat','repeat',id)}${actionButton('Make favorite','favoriteFrom',id)}${actionButton('Correction history','history',id)}</div>${t.receiptId?`<img class="receipt-full" src="/receipt/${esc(t.receiptId)}" alt="Saved receipt">`:''}${t.splits?`<details open><summary>Category split</summary>${t.splits.map(s=>`<p>${esc(s.category)} · RM ${esc(s.amount)}</p>`).join('')}</details>`:''}${t.originalCurrency?`<p class="note">${esc(t.originalCurrency)} ${esc(t.originalAmount)} · settled ${money(t.amount)} · included fee RM ${esc(t.foreignFee||'0')} · implied MYR rate ${esc(t.exchangeRate||'—')}</p>`:''}${t.person?`<p class="note">Shared with ${esc(t.person)} · your share RM ${esc(t.ownAmount)}</p>`:''}${t.tags?.length?`<p class="note">${esc(Array.isArray(t.tags)?t.tags.join(' · '):t.tags)}</p>`:''}`)};
function scanDialog(){modal('Scan a receipt',`<p class="note">Choose a clear image or take a photo. Recognition runs on your device. Check the suggested total, date and merchant before recording.</p>${select('Text model','ocrLanguage',[['latin','English / Bahasa Melayu'],['chinese','Chinese + Latin']],'latin')}<div class="tools-grid">${actionButton('Take photo','receiptCamera')}${actionButton('Choose image','receiptPick')}</div>`)}
function insights(){let r=reportData;if(!r){toast('Open the Android app to calculate reports.');return}let max=Math.max(1,...r.months.map(m=>m.spent));modal('Your money, in perspective',`<p class="eyebrow muted">${esc(r.start)} — ${esc(r.end)} · END EXCLUSIVE</p><div class="insight-grid"><div class="soft-card"><p>Available estimate</p><strong class="money metric">${money(r.availableToSpend)}</strong></div><div class="soft-card"><p>Spent to today</p><strong class="money metric">${signedMoney(r.spent)}</strong></div></div><h3>Six budget cycles</h3><div class="bar-chart" role="img" aria-label="Spending in six cycles">${r.months.map(m=>`<div><span>${signedMoney(m.spent)}</span><i style="height:${Math.max(2,Math.max(0,m.spent)/max*110)}px"></i><small>${esc(dateLabel(m.start))}</small></div>`).join('')}</div><p class="note">Current cycle is incomplete. Comparable prior-cycle spending through the same number of days: ${signedMoney(r.previousComparable)}.</p><h3>Cash flow by cycle</h3>${r.months.map(m=>`<div class="detail-line"><span>${esc(dateLabel(m.start))}</span><span>In ${money(m.income)} · out ${signedMoney(m.spent)}<br>Net ${signedMoney((m.income||0)-m.spent)}</span></div>`).join('')}<h3>What is reserved?</h3>${[['Liquid account balances',r.liquid],['Card and installment debt',-r.cardReserve],['Unpaid bills before cycle end',-r.billsReserve],['Earmarked goals',-r.goalReserve]].map(([label,n])=>`<div class="detail-line"><span>${label}</span><span>${signedMoney(n)}</span></div>`).join('')}<p class="note">Estimate from recorded balances only. Card repayment plans are excluded from bill reserves because the card debt is already reserved. Check missing opening balances and reconcile regularly.</p><h3>Category spending this cycle</h3>${categories.map(c=>[c[0],spendFor(c[0])]).filter(c=>c[1]).map(c=>`<div class="detail-line"><span>${esc(c[0])}</span><span>${signedMoney(c[1])}</span></div>`).join('')}`)}
function favoriteForm(t={}){modalContext=t;modal('Quick favorite',`<form data-extra="favorite">${field('Favorite name','name',t.name||t.merchant||'','text','required maxlength="80"')}${field('Amount (RM)','amount',typeof t.amount==='number'?amount(t.amount):t.amount||'','text','required inputmode="decimal"')}${acctSelect(t.account)}${categorySelect(t.category)}${field('Merchant','merchant',t.merchant||'','text','maxlength="120"')}${formFooter('Save favorite')}</form>`)}
function ruleForm(r={}){modalContext=r;modal('Merchant suggestion rule',`<form data-extra="rule">${field('Merchant contains','match',r.match||'','text','required maxlength="120" placeholder="e.g. Grab"')}${categorySelect(r.category)}${subcategorySelect(r.category||'Miscellaneous',r.subcategory||'')}${select('Suggest account','account',[['','Leave for me to choose'],...state.accounts.map(a=>[a.id,a.name])],r.account||'')}${select('Limit to source','source',[['','Any source'],...state.sources.map(s=>[s.package,s.name])],r.source||'')}${field('Priority (0–100)','priority',r.priority??10,'number','min="0" max="100"')}${check('Enabled','enabled',r.enabled!==false)}<p class="note">Preview: future merchants containing “${esc(r.match||'your text')}” get these suggestions. Saved transactions stay as recorded.</p><div id="rule-preview" class="note"></div>${formFooter('Save rule')}</form>`)}
function automationForm(){let s=state.settings;modal('Reminders & privacy',`<form data-extra="automation">${check('Automatically record notifications using history / Miscellaneous','autoRecord',s.autoRecord!==false)}${check('Read payment notifications from all bank & wallet apps','captureAllSources',s.captureAllSources!==false)}${check('Always-on persistent task scheduler (auto-restarts unless Force Stopped)','alwaysOnScheduler',s.alwaysOnScheduler!==false)}${check('Auto-open MoneyLens when phone restarts','autoOpenOnBoot',s.autoOpenOnBoot!==false)}${check('BNPL, PTPTN, bill and cancellation reminders','reminders',s.reminders!==false)}${check('Budget threshold alerts','budgetAlerts',s.budgetAlerts!==false)}${field('Budget alert threshold (%)','threshold',s.threshold||80,'number','min="1" max="100" required')}${check('One daily Inbox digest instead of individual prompts','digest',s.digest)}${field('Digest hour (0–23)','digestHour',s.digestHour??19,'number','min="0" max="23" required')}${check('Quiet hours','quietEnabled',s.quietEnabled)}<div class="form-grid">${field('Quiet from hour','quietStart',s.quietStart??22,'number','min="0" max="23" required')}${field('Quiet until hour','quietEnd',s.quietEnd??8,'number','min="0" max="23" required')}</div>${check('Show available estimate on home-screen widget','widgetAmounts',s.widgetAmounts)}${check('Capture while MoneyLens is closed or locked','captureWhileLocked',s.captureWhileLocked!==false)}<p class="note">Always-on task scheduler keeps auto-capture and BNPL/PTPTN due reminders active continuously across restarts.</p>${formFooter('Save preferences')}</form>`)}
window.csvLoaded=info=>{importInfo=info;let rows=[[-1,'Not mapped'],...info.headers.map((h,i)=>[i,h||'Column '+(i+1)])];const guess=name=>info.headers.findIndex(h=>h.toLowerCase().includes(name));modal('Map your statement columns',`<form data-extra="csvMap"><p class="note">${info.count} rows. Choose how your file maps to MoneyLens, then review before saving.</p>${['date','amount','merchant','category','kind','note'].map(k=>select(k[0].toUpperCase()+k.slice(1)+' column',k,rows,guess(k))).join('')}${acctSelect()}${select('Date format','dateFormat',[['iso','YYYY-MM-DD'],['dmy','DD/MM/YYYY'],['mdy','MM/DD/YYYY']],'iso')}${select('Default transaction type','defaultKind',[['expense','Expense'],['income','Income'],['refund','Refund']],'expense')}${check('Signed amounts: negative expenses, positive income','signed')}<details><summary>First rows</summary><pre class="csv-sample">${esc(info.sample.map(r=>r.join(' | ')).join('\n'))}</pre></details>${formFooter('Preview import')}</form>`)};
function csvReview(rows){importPreview=rows;modal('Review CSV import',`<form data-extra="csvCommit"><p class="note">Possible duplicates start unchecked. Re-imported rows are blocked. Transfers need manual entry.</p><div class="review-list">${rows.map((r,i)=>`<label class="import-row"><input type="checkbox" name="row" value="${i}" ${r.error||r.duplicate?'disabled':r.possibleDuplicate?'':'checked'}><span><strong>${esc(r.merchant||'Row '+r.row)} ${r.amount?'· RM '+esc(r.amount):''}</strong><small>${esc(r.error||(r.date+' · '+r.kind+' · '+r.category))}</small>${r.duplicate?'<b>Already imported</b>':r.possibleDuplicate?'<b>Possible duplicate — check manually</b>':''}</span></label>`).join('')}</div>${formFooter('Import selected rows')}</form>`)}
function batchForm(){let ds=state.drafts.filter(d=>d.state==='review').slice(0,100);modal('Review selected payments',`<form data-extra="batch"><p class="note">Choose payments with correct amount and category. The account below applies to every selected payment.</p>${acctSelect()}<div class="review-list">${ds.map(d=>`<label class="import-row"><input type="checkbox" name="draft" value="${esc(d.id)}" ${d.amount>0?'':'disabled'}><span><strong>${esc(d.merchant)} · ${money(d.amount)}</strong><small>${esc(d.category)} · ${esc(d.date)} · ${esc(d.reason)}</small></span></label>`).join('')}</div>${formFooter('Record selected payments')}${actionButton('Ignore selected','ignoreSelected','','ghost')}</form>`)}
function linkForm(id,bill=false){modalContext={id};modal(bill?'Match an existing payment':'Already recorded?',`<form data-extra="${bill?'matchBill':'linkDraft'}"><p class="note">Choose the same payment already in your ledger. This links the record without creating another expense.</p>${select('Recorded transaction','transactionId',validTx().filter(t=>!['opening','adjustment'].includes(t.kind)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,200).map(t=>[t.id,t.date+' · '+(t.merchant||t.category)+' · '+money(t.amount)]),'')}${formFooter('Link payment')}</form>`)}
const baseTransactions=transactions;
transactions=()=>`<div class="tools-grid" style="margin-bottom:18px">${actionButton('Filter records','filters')}${actionButton('Import CSV','csvPick')}${actionButton('Insights','insights')}</div>${Object.keys(advancedFilters).length?`<p class="note">Advanced filters active ${actionButton('Clear','clearFilters','','ghost')}</p>`:''}`+baseTransactions();
const baseTransactionList=transactionList;
transactionList=(rows,grouped=true)=>{if(page==='transactions')rows=rows.filter(t=>(!advancedFilters.from||t.date>=advancedFilters.from)&&(!advancedFilters.until||t.date<=advancedFilters.until)&&(!advancedFilters.account||t.account===advancedFilters.account||t.to===advancedFilters.account)&&(!advancedFilters.min||t.amount>=Number(advancedFilters.min)*100)&&(!advancedFilters.max||t.amount<=Number(advancedFilters.max)*100)&&(!advancedFilters.source||(t.source||'manual')===advancedFilters.source)&&(!advancedFilters.tag||String(t.tags||'').toLowerCase().includes(advancedFilters.tag.toLowerCase())));return baseTransactionList(rows,grouped)};
document.addEventListener('input',e=>{if(e.target.name==='match'){let needle=e.target.value.toLowerCase();$('#rule-preview').textContent='Matching examples in your ledger: '+[...new Set(validTx().filter(t=>needle&&t.merchant?.toLowerCase().includes(needle)).map(t=>t.merchant))].slice(0,5).join(', ')}});
document.addEventListener('change',async e=>{const x=e.target;try{
 if(x.name==='category'&&$('#f-subcategory'))$('#f-subcategory').innerHTML=subcatOptions(x.value,'');
 if(x.id==='autoRecordToggle')await mutate('settings',{autoRecord:x.checked},x.checked?'Auto-record enabled.':'Auto-record paused.');
 if(x.id==='captureAllToggle')await mutate('settings',{captureAllSources:x.checked},x.checked?'Reading all bank & wallet apps.':'Restricted to selected apps.');
 if(x.id==='alwaysOnToggle')await mutate('settings',{alwaysOnScheduler:x.checked},x.checked?'Always-on task scheduler active.':'Always-on task scheduler paused.');
 if(x.id==='autoOpenToggle')await mutate('settings',{autoOpenOnBoot:x.checked},x.checked?'Will auto-open on phone restart.':'Auto-open on restart disabled.');
 if(x.matches('.source-account')){await mutate('source',{package:x.dataset.package,name:x.dataset.name,enabled:true,account:x.value},'Linked account saved.');}
 if(x.matches('.source-toggle')&&$('#source-search')){setTimeout(()=>renderSources($('#source-search').value),80);}
}catch(err){toast(err.message)}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id;try{switch(action){
case 'quickNote':quickNoteForm(id);break;
case 'applyHistoryYes':await mutate('updateMerchantHistory',modalContext,'Updated previous records and saved rule for future.');close();break;
case 'overlayPermission':await call('overlayPermission');break;
case 'batteryOptimization':await call('batteryOptimization');break;
case 'openTaxPlan':page='plan';planTab='tax';render();window.scrollTo(0,0);break;
case 'openBnplPlan':page='plan';planTab='bills';render();window.scrollTo(0,0);break;
case 'presetReminder':{
 const presets={
  ptptn:{name:'PTPTN Study Loan Repayment',reminderType:'ptptn',category:'Loans, BNPL & Credit',subcategory:'PTPTN Study Loan',amount:15000,frequency:'monthly',remindDaysBefore:3,remindTime:'09:00'},
  spaylater:{name:'SPayLater (Shopee BNPL)',reminderType:'bnpl',category:'Loans, BNPL & Credit',subcategory:'BNPL (SPayLater / GrabPayLater / Atome)',amount:5000,frequency:'monthly',remindDaysBefore:3,remindTime:'10:00'},
  grabpaylater:{name:'GrabPayLater Monthly Bill',reminderType:'bnpl',category:'Loans, BNPL & Credit',subcategory:'BNPL (SPayLater / GrabPayLater / Atome)',amount:5000,frequency:'monthly',remindDaysBefore:3,remindTime:'10:00'},
  atome:{name:'Atome BNPL Installment',reminderType:'bnpl',category:'Loans, BNPL & Credit',subcategory:'BNPL (SPayLater / GrabPayLater / Atome)',amount:5000,frequency:'everyXDays',intervalDays:30,remindDaysBefore:3,remindTime:'10:00'},
  creditcard:{name:'Credit Card Statement Due',reminderType:'credit',category:'Loans, BNPL & Credit',subcategory:'Credit Card Bill',amount:20000,frequency:'monthly',remindDaysBefore:3,remindTime:'09:00'}
 };
 billForm(presets[id]||{});break;
}
case 'testReminder':await mutate('testReminder',{id},'Test reminder notification posted!');break;
case 'autoFillTaxReliefs':{
 const det=reportData?.taxEstimate?.ledgerDetected||{};
 const form=$('#tax-profile-form');
 if(form){
  for(const k of ['lifestyle','sports','medical','lifeInsurance','medicalInsurance','education','sspnPrs','zakat']){
   if(det[k]!==undefined&&form.elements[k])form.elements[k].value=(det[k]/100).toFixed(2);
  }
  toast('Filled reliefs from your recorded expenses. Tap Calculate & Save to apply.');
 }
 break;
}
case 'removeCategory':await mutate('removeCategory',{name:b.dataset.name},`Removed category "${b.dataset.name}".`);categoriesModal();break;
case 'removeSubcategory':await mutate('removeSubcategory',{category:b.dataset.category,subcategory:b.dataset.subcategory},`Removed subcategory "${b.dataset.subcategory}".`);categoriesModal();break;
case 'scan':scanDialog();break;
case 'receiptPick':case 'receiptCamera':await call(action,{language:$('.modal select').value});close();break;
case 'paste':modal('Paste payment text',`<form data-extra="paste"><label for="pasteText">Notification or receipt text</label><textarea name="text" id="pasteText" maxlength="4000" required rows="6" placeholder="Paste the payment message here"></textarea><p class="note">Automatically parses and records the payment into your ledger.</p>${formFooter('Record payment')}</form>`);break;
case 'insights':insights();break;
case 'addSplit':$('#split-rows').insertAdjacentHTML('beforeend',splitRow());break;
case 'removeSplit':b.closest('.split-row').remove();break;
case 'shared':txForm({kind:'shared'});break;
case 'repay':{let r=reportData.receivables.find(x=>x.id===id);txForm({kind:'reimbursement',amount:r.remaining,reimbursementFor:id,merchant:'Repayment · '+r.person,category:'Repayment'});break}
case 'repeat':{let t=state.transactions.find(x=>x.id===id);if(['reimbursement','opening','adjustment'].includes(t.kind)){toast('Use the account reconciliation or repayment workflow for this record.');break}txForm({kind:t.kind,amount:t.amount,account:t.account,to:t.to,category:t.category,subcategory:t.subcategory,merchant:t.merchant,tags:t.tags,splits:t.splits,person:t.person,ownAmount:t.ownAmount,date:today()});break}
case 'favoriteFrom':favoriteForm(state.transactions.find(x=>x.id===id));break;
case 'useFavorite':{let f=state.favorites.find(x=>x.id===id);txForm({...f,kind:'expense',date:today(),key:cryptoId()});break}
case 'favorites':showFavorites();break;
case 'unusedFavorites':modal('Quick favorites',`${state.favorites.map(f=>`<div class="setting-row"><div class="grow"><h3>${esc(f.name)}</h3><p>RM ${esc(f.amount)}</p></div>${actionButton('Edit','editFavorite',f.id)}${actionButton('Remove','deleteFavorite',f.id,'ghost')}</div>`).join('')||'<p class="note">Save common purchases for faster entry.</p>'}${actionButton('Create favorite','editFavorite')}`);break;
case 'editFavorite':favoriteForm(state.favorites.find(f=>f.id===id)||{});break;
case 'deleteFavorite':await mutate('deleteExtra',{table:'favorites',id});close();break;
case 'categories':categoriesModal();break;
case 'rules':modal('Merchant rules',`${state.rules.map(r=>`<div class="setting-row"><div class="grow"><h3>${esc(r.match)}</h3><p>${esc(r.category)}${r.subcategory?' › '+esc(r.subcategory):''} · ${r.enabled?'Enabled':'Paused'} · priority ${r.priority}</p></div>${actionButton('Edit','editRule',r.id)}${actionButton('Delete','deleteRule',r.id,'ghost')}</div>`).join('')||'<p class="note">Teach MoneyLens your own merchant suggestions.</p>'}${actionButton('Add rule','editRule')}${state.ruleHistory?.length?actionButton('Undo last rule change','undoRule','','ghost'):''}`);break;
case 'editRule':ruleForm(state.rules.find(r=>r.id===id)||{});break;
case 'undoRule':await mutate('undoRule',{},'Last rule change undone.');close();break;
case 'deleteRule':await mutate('deleteExtra',{table:'rules',id});close();break;
case 'automation':automationForm();break;
case 'autoBackup':case 'backupNow':case 'stopAutoBackup':await call(action);await window.nativeRefresh();break;
case 'csvPick':await call('csvPick');break;
case 'imports':modal('Import history',`${state.imports.slice().reverse().map(b=>`<div class="setting-row"><div class="grow"><h3>${esc(b.date)} · ${b.count} rows</h3><p>${b.undone?'Undone':'Imported'} · ${esc(b.name)}</p></div>${!b.undone?actionButton('Undo import','undoImportConfirm',b.id):''}</div>`).join('')||'<p class="note">No imports yet.</p>'}`);break;
case 'undoImportConfirm':modal('Undo this import?',`<p class="note">Unedited records in this batch will be voided. Records you have corrected remain. The original file cannot be accidentally imported again.</p>${actionButton('Undo import','undoImport',id,'danger')}`);break;
case 'undoImport':await mutate('undoImport',{id},'Import reversed. Edited records were kept.');close();break;
case 'recoverConfirm':modal('Restore previous local copy?',`<p class="note">This replaces your current ledger with the copy retained before your last restore. Export a backup first if you want to keep current changes.</p>${actionButton('Restore local copy','recover','','danger')}`);break;
case 'recover':await mutate('recover',{},'Previous local copy restored.');close();break;
case 'diagnostics':{let d=await call('diagnostics');modalContext={diagnostics:JSON.stringify(d,null,2)};modal('Capture diagnostics',`<p class="note">This preview contains no merchants, amounts, account numbers or raw notifications.</p><pre class="csv-sample">${esc(JSON.stringify(d,null,2))}</pre>${actionButton('Export these diagnostics','diagnosticExport')}`);break}
case 'diagnosticExport':await call('diagnosticExport',{text:modalContext.diagnostics});break;
case 'batch':batchForm();break;
case 'ignoreSelected':{let ids=[...document.querySelectorAll('input[name=draft]:checked')].map(x=>x.value);await mutate('ignoreBatch',{ids},'Selected suggestions ignored.');close();break}
case 'linkDraft':linkForm(id);break;
case 'matchBill':linkForm(id,true);break;
case 'cancelBill':{let bill=state.bills.find(x=>x.id===id);await mutate('cancelBill',{id,cancelled:!bill.cancelled},'Plan updated.');close();break}
case 'deleteBillExtra':await mutate('deletePlan',{table:'bills',id},'Reminder removed.');close();break;
case 'subscription':billForm({...reportData.subscriptions[Number(id)],subscription:true});break;
case 'reconcile':modal('Compare with your statement',`<form data-extra="reconcile">${acctSelect()}${field('As-of date','date',today(),'date','required')}${field('Statement balance (RM)','actual','','text','required inputmode="decimal"')}<p class="note">For a card, enter debt as a negative balance, such as -125.50. You will review the difference before adjusting.</p>${field('Note','note','','text','maxlength="500"')}${formFooter('Compare balances')}</form>`);break;
case 'saveReconcile':await mutate('reconcile',{...modalContext,adjust:false},'Balance check saved.');close();break;
case 'adjustReconcile':await mutate('reconcile',{...modalContext,adjust:true},'Explicit balance adjustment saved.');close();break;
case 'installment':modal('Plan an installment purchase',`<form data-extra="installment">${field('Purchase name','name','','text','required maxlength="80"')}${field('Purchase price (RM)','amount','','text','required inputmode="decimal"')}${field('Total fees or interest (RM)','fee','0','text','required inputmode="decimal"')}${field('Number of monthly payments','months','12','number','min="2" max="60" required')}${field('First payment date','date',today(),'date','required')}${acctSelect()}${categorySelect('Shopping')}<p class="note">The full purchase plus fees is recorded once as spending on a new installment liability account. Monthly payments are transfers that reduce this debt.</p>${formFooter('Create purchase and payment plan')}</form>`);modalContext={key:cryptoId()};break;
case 'filters':modal('Find the records you need',`<form data-extra="filters"><div class="form-grid">${field('From date','from',advancedFilters.from||'','date')}${field('Through date','until',advancedFilters.until||'','date')}</div>${select('Account','account',[['','All accounts'],...state.accounts.map(a=>[a.id,a.name])],advancedFilters.account||'')}<div class="form-grid">${field('Minimum RM','min',advancedFilters.min||'','number','min="0" step="0.01"')}${field('Maximum RM','max',advancedFilters.max||'','number','min="0" step="0.01"')}</div>${field('Tag contains','tag',advancedFilters.tag||'')}${select('Source','source',[['','All sources'],['manual','Manual entry'],...[...new Set(validTx().map(t=>t.source).filter(Boolean))].map(s=>[s,s])],advancedFilters.source||'')}${formFooter('Apply filters')}</form>`);break;
case 'clearFilters':advancedFilters={};render();break;
case 'history':{let t=state.transactions.find(x=>x.id===id),rows=[t];while(t.replaces){t=state.transactions.find(x=>x.id===t.replaces);if(!t)break;rows.push(t)}modal('Correction history',rows.map((r,i)=>`<section class="soft-card"><h3>${i===0?'Current record':'Previous version'}</h3><p>${esc(r.date)} · ${esc(r.merchant)} · ${money(r.amount)}</p><p class="note">${esc(r.category)}${r.subcategory?' › '+esc(r.subcategory):''} · ${esc(r.note||'')} · ${r.voided?'Superseded or voided':'Active'}</p></section>`).join(''));break}
}}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{let form=e.target;if(!form.dataset.extra)return;e.preventDefault();if(busy)return;const type=form.dataset.extra,args=Object.fromEntries(new FormData(form));const button=form.querySelector('button[type=submit]');busy=true;if(button)button.disabled=true;try{let method=type,stay=false;
 switch(type){
 case 'quickNote':{
  args.id=modalContext.id;args.applyHistory=!!form.elements.applyHistory?.checked;
  const m=modalContext.merchant,oldCat=modalContext.oldCategory,newCat=args.category||oldCat,diffCount=sameMerchantCount(m,args.id,newCat);
  if(!args.applyHistory&&m&&newCat!==oldCat&&diffCount>0){
   await mutate('quickNote',args,'Saved.');busy=false;
   modalContext={merchant:m,category:newCat,subcategory:args.subcategory||'',account:modalContext.account||''};
   modal('Update previous history too?',`<p class="note">Found <strong>${diffCount}</strong> previous transaction${diffCount===1?'':'s'} for <strong>${esc(m)}</strong> with a different category. Would you like to update their category to <strong>${esc(newCat)}</strong> and remember it for future notifications?</p><div class="form-footer" style="margin-top:20px"><button class="btn ghost" data-action="close">Only this one</button><button class="btn" data-action="applyHistoryYes">Update all & remember</button></div>`);
   return;
  }
  break;
 }
 case 'category':case 'addSubcategory':
  await mutate(method,args,'Category list updated.');busy=false;categoriesModal();return;
 case 'taxProfile':
  await mutate('taxProfile',args,'LHDN tax estimate updated.');busy=false;render();return;
 case 'favorite':if(state.favorites.some(f=>f.id===modalContext.id))args.id=modalContext.id;break;
 case 'rule':if(modalContext.id)args.id=modalContext.id;args.priority=Number(args.priority);args.enabled=form.elements.enabled.checked;break;
 case 'automation':method='settings';for(const name of ['quietEnabled','digest','reminders','budgetAlerts','widgetAmounts','captureWhileLocked','autoRecord','captureAllSources','autoOpenOnBoot','alwaysOnScheduler'])if(form.elements[name])args[name]=form.elements[name].checked;for(const name of ['quietStart','quietEnd','digestHour','threshold'])args[name]=Number(args[name]);break;
 case 'csvMap':for(let k of ['date','amount','merchant','category','kind','note'])args[k]=Number(args[k]);args.signed=form.elements.signed.checked;csvReview(await call('csvPreview',args));stay=true;break;
 case 'csvCommit':args.indices=[...form.querySelectorAll('input[name=row]:checked')].map(x=>Number(x.value));if(!args.indices.length)throw new Error('Choose at least one valid row.');method='csvCommit';break;
 case 'batch':{let ids=[...form.querySelectorAll('input[name=draft]:checked')].map(x=>x.value);if(!ids.length)throw new Error('Select the payments you checked.');args.rows=ids.map(id=>{const d=state.drafts.find(x=>x.id===id);return {...d,amount:amount(d.amount),account:args.account,draftId:id,draftRevision:d.revision||1,key:'draft:'+id}});method='confirmBatch';break}
 case 'linkDraft':case 'matchBill':args.id=modalContext.id;break;
 case 'reconcile':{let actual=Number(args.actual);if(!Number.isFinite(actual)||!/^[-]?\d+([.]\d{1,2})?$/.test(args.actual))throw new Error('Enter a balance with at most two decimal places.');let recorded=validTx().filter(t=>t.date<=args.date).reduce((sum,t)=>sum+t.postings.filter(p=>p.account===args.account).reduce((n,p)=>n+p.amount,0),0);modalContext=args;modal('Review balance difference',`<div class="detail-line"><span>Recorded</span><strong>${signedMoney(recorded)}</strong></div><div class="detail-line"><span>Statement</span><strong>${signedMoney(Math.round(actual*100))}</strong></div><div class="detail-line"><span>Difference</span><strong>${signedMoney(Math.round(actual*100)-recorded)}</strong></div><p class="note">Check missing or duplicate transactions first. Saving a check keeps a comparison record. An adjustment changes the account balance through an explicit equity posting.</p><div class="tools-grid">${actionButton('Save comparison only','saveReconcile')}${actionButton('Record adjustment','adjustReconcile','','ghost')}</div>`);stay=true;break}
 case 'installment':args.months=Number(args.months);args.key=modalContext.key;break;
 case 'filters':advancedFilters=Object.fromEntries(Object.entries(args).filter(([k,v])=>v));render();stay=true;busy=false;close();break;
 }
 if(!stay){await mutate(method,args,'Saved on your device.');busy=false;close();if(type==='paste'){page='inbox';render()}}busy=false;
 }catch(err){busy=false;const error=form.querySelector('.error');if(error)error.textContent=err.message;else toast(err.message)}finally{if(button)button.disabled=false}
});
if(state)render();

function showFavorites(){modal('Quick favorites',`${state.favorites.map(f=>`<div class="setting-row"><div class="grow"><h3>${esc(f.name)}</h3><p>RM ${esc(f.amount)} · ${esc(f.category)} · ${esc(account(f.account).name)}</p></div>${actionButton('Use','useFavorite',f.id)}${actionButton('Edit','editFavorite',f.id,'ghost')}${actionButton('Remove','deleteFavorite',f.id,'ghost')}</div>`).join('')||'<p class="note">Save common purchases for one-tap entry on Home and the Android app icon.</p>'}${actionButton('Create favorite','editFavorite')}`)}
